"use strict";(globalThis.webpackChunksoft_where=globalThis.webpackChunksoft_where||[]).push([[8130],{7735(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"graduation-experience-yan-jiahao","metadata":{"permalink":"/blog/graduation-experience-yan-jiahao","source":"@site/blog/2026-07-19-graduation-experience-yan-jiahao.md","title":"\u6bd5\u8bbe\u7ecf\u9a8c\u5206\u4eab\uff1a\u6d41\u7a0b\u3001\u9009\u9898\u4e0e\u7b54\u8fa9","description":"\u95eb\u4f73\u8c6a\u540c\u5b66\u5206\u4eab\u8f6f\u4ef6\u5b66\u9662\u672c\u79d1\u6bd5\u4e1a\u8bbe\u8ba1\u4ece\u9009\u9898\u3001\u5f00\u9898\u3001\u4e2d\u671f\u5230\u7ed3\u9898\u7b54\u8fa9\u7684\u5b8c\u6574\u7ecf\u9a8c\u3002","date":"2026-07-19T00:00:00.000Z","tags":[{"inline":false,"label":"\u6bd5\u8bbe\u7ecf\u9a8c\u5206\u4eab","permalink":"/blog/tags/graduation-experience","description":"\u8f6f\u4ef6\u5b66\u9662\u672c\u79d1\u6bd5\u4e1a\u8bbe\u8ba1\u7ecf\u9a8c\u5206\u4eab"}],"readingTime":4.23,"hasTruncateMarker":true,"authors":[{"name":"\u95eb\u4f73\u8c6a","title":"\u5fae\u4fe1\uff1aguangmingzhengda64","page":{"permalink":"/blog/authors/yanjiahao"},"imageURL":"https://soft-where-21.github.io/file/graduation_work/avatar/%E9%97%AB%E4%BD%B3%E8%B1%AA.jpg","key":"yanjiahao"}],"frontMatter":{"slug":"graduation-experience-yan-jiahao","title":"\u6bd5\u8bbe\u7ecf\u9a8c\u5206\u4eab\uff1a\u6d41\u7a0b\u3001\u9009\u9898\u4e0e\u7b54\u8fa9","authors":["yanjiahao"],"tags":["graduation-experience"],"description":"\u95eb\u4f73\u8c6a\u540c\u5b66\u5206\u4eab\u8f6f\u4ef6\u5b66\u9662\u672c\u79d1\u6bd5\u4e1a\u8bbe\u8ba1\u4ece\u9009\u9898\u3001\u5f00\u9898\u3001\u4e2d\u671f\u5230\u7ed3\u9898\u7b54\u8fa9\u7684\u5b8c\u6574\u7ecf\u9a8c\u3002"},"unlisted":false,"nextItem":{"title":"\u6bd5\u8bbe\u7ecf\u9a8c\u5206\u4eab\uff1a\u91cd\u89c6\u89c4\u8303\uff0c\u63d0\u524d\u51c6\u5907","permalink":"/blog/graduation-experience-zhou-qi-shun"}},"content":"\u6bd5\u4e1a\u8bbe\u8ba1\u662f\u6bd5\u4e1a\u524d\u7684\u6700\u540e\u4e00\u73af\uff0c\u57fa\u672c\u6b63\u5e38\u5bf9\u5f85\u90fd\u53ef\u4ee5\u987a\u5229\u5b8c\u6210\u3002\u592a\u6446\u53ef\u80fd\u4f1a\u8fdb\u5165\u4e8c\u8fa9\u6216\u672b\u4f4d\u590d\u5ba1\uff0c\u6d41\u7a0b\u4e0a\u9ebb\u70e6\u4e00\u4e9b\uff0c\u6240\u4ee5\u5927\u5bb6\u8fd8\u662f\u5e94\u8be5\u8ba4\u771f\u5bf9\u5f85\uff0c\u7279\u522b\u662f\u6307\u5bfc\u8001\u5e08\u4e5f\u662f\u81ea\u5df1\u8bfb\u7814\u5bfc\u5e08\u7684\u60c5\u51b5\u3002\\n\\n\u5f00\u9898\u3001\u4e2d\u671f\u3001\u7ed3\u9898\u73af\u73af\u76f8\u6263\u3002\u524d\u9762\u505a\u597d\u4e86\uff0c\u4e00\u4e9b\u6587\u5b57\u6750\u6599\u548c\u56fe\u7247\u90fd\u53ef\u4ee5\u590d\u7528\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u65f6\u95f4\u7ebf\\n\\n\u8f6f\u4ef6\u5b66\u9662\u7684\u5f00\u9898\u5f88\u65e9\uff0c\u4e2d\u671f\u4e5f\u504f\u65e9\uff0c\u7ed3\u9898\u65f6\u95f4\u5219\u548c\u5176\u4ed6\u5b66\u9662\u5dee\u4e0d\u591a\u3002\\n\\n- \u5f00\u9898\u5728 11 \u6708\u5e95\u3002\u4e3a\u4e86\u5b8c\u6210\u5f00\u9898\u62a5\u544a\u548c PPT\uff0c\u5927\u6982\u9700\u8981\u63d0\u524d 2\uff5e3 \u5468\u5f00\u59cb\u51c6\u5907\u3002\\n- \u4e2d\u671f\u5728 4 \u6708\u4e2d\u65ec\u3002\\n- \u7ed3\u9898\u5728 6 \u6708\u521d\u3002\u7ed3\u9898\u524d\uff0c5 \u6708 11 \u65e5\u5c31\u8981\u8fdb\u884c\u81ea\u67e5\u91cd\uff0c\u968f\u540e\u662f\u6559\u5e08\u67e5\u91cd\uff0c\u76f8\u5f53\u4e8e\u8fd9\u65f6\u8bba\u6587\u8981\u5168\u90e8\u5b8c\u6210\u30025 \u6708 18 \u65e5\u622a\u6b62\u63d0\u4ea4\u76f2\u5ba1\u7a3f\uff0c\u4e4b\u540e\u6839\u636e\u53cd\u9988\u610f\u89c1\u4fee\u6539\u3002\u6700\u7ec8\u7a3f\u5219\u5728\u7b54\u8fa9\u540e\u4fee\u6539\u5e76\u63d0\u4ea4\u3002\\n\\n## \u9009\u9898\\n\\n\u9009\u9898\u57fa\u672c\u7b49\u4e8e\u9009\u62e9\u6bd5\u8bbe\u5bfc\u5e08\uff0c\u901a\u5e38\u5206\u4e3a\u4ee5\u4e0b\u51e0\u79cd\u60c5\u51b5\u3002\\n\\n### \u672c\u6821\u4fdd\u7814\\n\\n\u5bfc\u5e08\u5f80\u5f80\u4f1a\u76f4\u63a5\u6307\u5b9a\u9898\u76ee\uff0c\u6216\u8005\u63d0\u4f9b\u51e0\u4e2a\u9898\u76ee\u4f9b\u9009\u62e9\u3002\u9075\u5faa\u5bfc\u5e08\u5b89\u6392\u5373\u53ef\u3002\\n\\n### \u5916\u6821\u4fdd\u7814\\n\\n\u5982\u679c\u5df2\u7ecf\u63d0\u524d\u8fdb\u7ec4\uff0c\u9898\u76ee\u4e00\u822c\u7531\u5916\u6821\u8001\u5e08\u7ed9\u51fa\uff0c\u540c\u65f6\u9700\u8981\u5728\u672c\u6821\u627e\u4e00\u4f4d\u8001\u5e08\u6302\u540d\u3002\u8fd9\u4f4d\u8001\u5e08\u4e3b\u8981\u8d1f\u8d23\u5728\u7cfb\u7edf\u4e0a\u586b\u5199\u4fe1\u606f\u3001\u7533\u62a5\u9898\u76ee\u548c\u6700\u540e\u7b7e\u5b57\u7b49\u3002\\n\\n\u5982\u679c\u6ca1\u6709\u63d0\u524d\u8fdb\u7ec4\uff0c\u5bfc\u5e08\u4e5f\u6ca1\u6709\u7ed9\u9898\u76ee\uff0c\u5219\u53ef\u4ee5\u53c2\u7167\u76f4\u63a5\u5de5\u4f5c\u7684\u9009\u9898\u65b9\u5f0f\u3002\\n\\n### \u8003\u7814\\n\\n\u5982\u679c\u6709\u660e\u786e\u7684\u8003\u7814\u76ee\u6807\u5e76\u4e14\u5df2\u7ecf\u8054\u7cfb\u8001\u5e08\uff0c\u53ef\u4ee5\u8bf7\u8001\u5e08\u6307\u5b9a\u9898\u76ee\uff1b\u5982\u679c\u6ca1\u6709\u8054\u7cfb\u8001\u5e08\uff0c\u540c\u6837\u53ef\u4ee5\u53c2\u7167\u76f4\u63a5\u5de5\u4f5c\u7684\u9009\u9898\u65b9\u5f0f\u3002\\n\\n### \u76f4\u63a5\u5de5\u4f5c\\n\\n\u53ef\u4ee5\u4e3b\u52a8\u8054\u7cfb\u611f\u5174\u8da3\u7684\u5bfc\u5e08\uff0c\u8be2\u95ee\u662f\u5426\u8fd8\u6709\u6307\u5bfc\u540d\u989d\uff0c\u518d\u8bf7\u5bfc\u5e08\u5206\u914d\u9898\u76ee\uff1b\u4e5f\u53ef\u4ee5\u76f4\u63a5\u5728\u6bd5\u8bbe\u7cfb\u7edf\u4e2d\u9009\u9898\u3002\u8001\u5e08\u4f1a\u5728\u7cfb\u7edf\u91cc\u5f00\u653e\u4e00\u4e9b\u9898\u76ee\uff0c\u53ef\u4ee5\u6839\u636e\u5174\u8da3\u9009\u62e9\uff0c\u800c\u4e14\u8fd9\u90e8\u5206\u6ca1\u6709\u5b66\u9662\u9650\u5236\u3002\\n\\n\u603b\u4f53\u800c\u8a00\uff0c\u8bfb\u7814\u7684\u540c\u5b66\u5927\u591a\u7531\u81ea\u5df1\u8bfb\u7814\u9636\u6bb5\u7684\u5bfc\u5e08\u6307\u5bfc\u672c\u79d1\u6bd5\u8bbe\uff0c\u8fd9\u6837\u90e8\u5206\u7814\u7a76\u5de5\u4f5c\u4e5f\u53ef\u4ee5\u4e3a\u8bfb\u7814\u505a\u94fa\u57ab\u3002\u76f4\u63a5\u5de5\u4f5c\u7684\u540c\u5b66\u53ef\u4ee5\u5c3d\u91cf\u9009\u62e9\u7b80\u5355\u3001\u53ef\u63a7\u7684\u9898\u76ee\u3002\\n\\n## \u5f00\u9898\\n\\n\u5f00\u9898\u6709\u8be6\u7ec6\u6a21\u677f\uff0c\u6309\u7167\u8981\u6c42\u586b\u5199\u5373\u53ef\uff0c\u9875\u6570\u548c\u683c\u5f0f\u8981\u6c42\u76f8\u5bf9\u5bbd\u677e\u3002\u5f53\u65f6\u6211\u7684\u5f00\u9898\u62a5\u544a\u6b63\u6587\u4e3a 12 \u9875\uff0c\u4e0d\u5305\u62ec\u53c2\u8003\u6587\u732e\u3002\\n\\n\u91cd\u70b9\u662f\u5b8c\u6210\u6587\u732e\u7efc\u8ff0\uff0c\u63d0\u51fa\u5927\u81f4\u7684\u7814\u7a76\u76ee\u6807\u548c\u65b9\u6cd5\uff0c\u5e76\u7ed9\u51fa\u603b\u4f53\u65b9\u6848\u4e0e\u8bba\u6587\u5de5\u4f5c\u8ba1\u5212\u3002\u7b54\u8fa9\u65f6\u95f4\u4e3a 10 \u5206\u949f\u6c47\u62a5\u52a0 5 \u5206\u949f\u95ee\u7b54\u3002\\n\\n## \u4e2d\u671f\\n\\n\u4e2d\u671f\u540c\u6837\u6709\u6a21\u677f\uff0c\u4f46\u5927\u90e8\u5206\u5e94\u8be5\u662f\u81ea\u5df1\u5b9e\u9645\u5b8c\u6210\u7684\u5185\u5bb9\u3002\u4e2d\u671f\u6750\u6599\u5f88\u5927\u4e00\u90e8\u5206\u53ef\u4ee5\u7528\u4e8e\u7ed3\u9898\uff0c\u56e0\u6b64\u8ba4\u771f\u51c6\u5907\u4e0d\u4f1a\u5403\u4e8f\u3002\u5f53\u65f6\u6211\u7684\u4e2d\u671f\u62a5\u544a\u6b63\u6587\u4e3a 18 \u9875\uff0c\u4e0d\u5305\u62ec\u53c2\u8003\u6587\u732e\u3002\\n\\n\u4e00\u822c\u6765\u8bf4\uff0c\u4e2d\u671f\u65f6\u6bd5\u8bbe\u5e94\u8be5\u5df2\u7ecf\u5b8c\u6210 80%\uff0c\u6838\u5fc3\u662f\u4ecb\u7ecd\u5f53\u524d\u8fdb\u5c55\u3002\u7b54\u8fa9\u65f6\u95f4\u540c\u6837\u4e3a 10 \u5206\u949f\u6c47\u62a5\u52a0 5 \u5206\u949f\u95ee\u7b54\u3002\\n\\n## \u7ed3\u9898\\n\\n\u7ed3\u9898\u6a21\u677f\u4e0d\u592a\u597d\u7528\uff0c\u800c\u4e14\u683c\u5f0f\u8981\u6c42\u5f88\u9ad8\uff0c\u4e00\u5b9a\u8981\u4e25\u683c\u5bf9\u7167\u6bd5\u8bbe\u624b\u518c\u68c0\u67e5\u3002\u5b57\u6570\u6ca1\u6709\u786c\u6027\u8981\u6c42\uff0c\u4f46\u4e00\u822c\u4f1a\u8fbe\u5230\u6b63\u6587 40 \u9875\u6216 2 \u4e07\u5b57\uff0c\u4e0d\u8db3\u65f6\u8001\u5e08\u901a\u5e38\u4f1a\u8981\u6c42\u8865\u5145\u3002\u6211\u7684\u6700\u7ec8\u7248\u6b63\u6587\u4e3a 43 \u9875\u30012.3 \u4e07\u5b57\uff0c\u4e0d\u5305\u62ec\u53c2\u8003\u6587\u732e\u3002\\n\\n\u7ed3\u9898\u6750\u6599\u9700\u8981\u5b8c\u6574\u5448\u73b0\u6240\u6709\u5de5\u4f5c\uff0c\u5177\u4f53\u5185\u5bb9\u6309\u7167\u6a21\u677f\u8981\u6c42\u7ec4\u7ec7\u5373\u53ef\uff0c\u4e5f\u53ef\u4ee5\u590d\u7528\u5f00\u9898\u548c\u4e2d\u671f\u7684\u5185\u5bb9\u3002\u6559\u52a1\u516c\u5e03\u7684\u7b54\u8fa9\u65f6\u95f4\u662f 15 \u5206\u949f\u6c47\u62a5\u52a0 15 \u5206\u949f\u95ee\u7b54\uff0c\u4f46\u5b9e\u9645\u6267\u884c\u4e0e\u7b54\u8fa9\u7ec4\u6709\u5173\u3002\\n\\n## \u505a\u56fe\\n\\n\u56fe\u7247\u4e0d\u4ec5\u53ef\u4ee5\u66f4\u76f4\u89c2\u5730\u5c55\u793a\u5185\u5bb9\uff0c\u4e5f\u5f88\u5bb9\u6613\u590d\u7528\u5230\u7b54\u8fa9 PPT \u4e2d\uff0c\u5e94\u8be5\u8ba4\u771f\u5236\u4f5c\u3002\u53ef\u4ee5\u5584\u7528 AI \u5de5\u5177\uff0c\u4e5f\u53ef\u4ee5\u5f15\u7528\u5176\u4ed6\u8bba\u6587\u4e2d\u7684\u56fe\u7247\uff0c\u4f46\u9700\u8981\u660e\u786e\u6807\u6ce8\u6765\u6e90\u3002\\n\\n## \u5173\u4e8e\u672b\u4f4d\u590d\u5ba1\\n\\n\u5f00\u9898\u6ca1\u6709\u672b\u4f4d\u590d\u5ba1\u3002\\n\\n\u4e2d\u671f\u901a\u5e38\u6bcf\u7ec4\u6700\u540e 1\uff5e2 \u540d\u9700\u8981\u518d\u6b21\u7b54\u8fa9\uff0c\u4e00\u822c\u4e3a 1 \u540d\u3002\u7ed3\u9898\u540c\u6837\u901a\u5e38\u6bcf\u7ec4\u6700\u540e 1\uff5e2 \u540d\u9700\u8981\u672b\u4f4d\u590d\u5ba1\uff0c\u4e3b\u8981\u662f\u4fee\u6539\u8bba\u6587\u540e\u518d\u7531\u8001\u5e08\u5ba1\u6838\u3002\u5373\u4f7f\u6ca1\u6709\u8fdb\u5165\u672b\u4f4d\u590d\u5ba1\uff0c\u5176\u4ed6\u540c\u5b66\u4e5f\u9700\u8981\u6309\u7167\u610f\u89c1\u4fee\u6539\u8bba\u6587\uff0c\u53ea\u662f\u672b\u4f4d\u590d\u5ba1\u7684\u5ba1\u6838\u53ef\u80fd\u66f4\u4e25\u683c\u3001\u4fee\u6539\u5185\u5bb9\u66f4\u591a\u3002\\n\\n## \u5173\u4e8e\u6210\u7ee9\u8bc4\u7ea7\\n\\n\u4f18\u79c0\u6709 20% \u7684\u6bd4\u4f8b\u9650\u5236\u3002\u4e0d\u540c\u5b66\u9662\u8bc4\u9009\u65b9\u5f0f\u4e0d\u540c\uff0c\u6709\u7684\u5b66\u9662\u8bc4\u9009\u4f18\u79c0\u6bd5\u8bbe\u8fd8\u9700\u8981\u518d\u6b21\u7b54\u8fa9\uff0c\u8f6f\u4ef6\u5b66\u9662\u5f80\u5e74\u4e0d\u9700\u8981\uff0c\u4f46\u89c4\u5219\u4e5f\u53ef\u80fd\u53d1\u751f\u53d8\u5316\u3002\\n\\n\u826f\u597d\u6ca1\u6709\u6bd4\u4f8b\u9650\u5236\u3002\u90e8\u5206\u5b66\u6821\u8981\u6c42\u4fdd\u7814\u540c\u5b66\u7684\u6bd5\u8bbe\u6210\u7ee9\u8fbe\u5230\u826f\u53ca\u4ee5\u4e0a\uff0c\u8fd9\u4e9b\u540c\u5b66\u9700\u8981\u7279\u522b\u7559\u610f\u3002\u4e2d\u7b49\u548c\u53ca\u683c\u662f\u5426\u6709\u6bd4\u4f8b\u8981\u6c42\u5219\u4e0d\u6e05\u695a\u3002\\n\\n## \u5173\u4e8e\u67e5\u91cd\u4e0e AI\\n\\n\u67e5\u91cd\u8981\u6c42\u4e3a 8%\u3002\u8fd9\u867d\u7136\u4e0d\u662f\u7edd\u5bf9\u7684\u6bd5\u4e1a\u6761\u4ef6\uff0c\u4f46\u8d85\u51fa\u540e\u9700\u8981\u5bfc\u5e08\u786e\u8ba4\u8bf4\u660e\uff0c\u6d41\u7a0b\u4f1a\u6bd4\u8f83\u9ebb\u70e6\uff0c\u800c\u4e14\u4efb\u4e00\u73af\u8282\u8d85\u8fc7 8% \u90fd\u4e0d\u80fd\u53c2\u8bc4\u4f18\u79c0\u6bd5\u4e1a\u8bbe\u8ba1\u3002\\n\\n\u4f7f\u7528 AI \u65f6\u8981\u6ce8\u610f\u63d0\u793a\u8bcd\u5e76\u63d0\u4f9b\u9002\u5f53\u8303\u4f8b\uff0c\u5c24\u5176\u4e0d\u8981\u4fdd\u7559\u660e\u663e\u7684 AI \u75d5\u8ff9\uff0c\u4f8b\u5982\u4e0d\u81ea\u7136\u7684\u5206\u70b9\u3001\u5012\u5f15\u53f7\u6216\u4e2d\u82f1\u6587\u6df7\u6742\u7b49\uff0c\u5426\u5219\u5f88\u5bb9\u6613\u5728\u7b54\u8fa9\u4e2d\u88ab\u8001\u5e08\u6307\u51fa\u3002"},{"id":"graduation-experience-zhou-qi-shun","metadata":{"permalink":"/blog/graduation-experience-zhou-qi-shun","source":"@site/blog/2026-07-19-graduation-experience-zhou-qi-shun.md","title":"\u6bd5\u8bbe\u7ecf\u9a8c\u5206\u4eab\uff1a\u91cd\u89c6\u89c4\u8303\uff0c\u63d0\u524d\u51c6\u5907","description":"\u5468\u5176\u987a\u540c\u5b66\u5206\u4eab\u8f6f\u4ef6\u5b66\u9662\u672c\u79d1\u6bd5\u4e1a\u8bbe\u8ba1\u5f00\u9898\u3001\u4e2d\u671f\u4e0e\u7ed3\u9898\u9636\u6bb5\u7684\u51c6\u5907\u91cd\u70b9\u3002","date":"2026-07-19T00:00:00.000Z","tags":[{"inline":false,"label":"\u6bd5\u8bbe\u7ecf\u9a8c\u5206\u4eab","permalink":"/blog/tags/graduation-experience","description":"\u8f6f\u4ef6\u5b66\u9662\u672c\u79d1\u6bd5\u4e1a\u8bbe\u8ba1\u7ecf\u9a8c\u5206\u4eab"}],"readingTime":2.82,"hasTruncateMarker":true,"authors":[{"name":"\u5468\u5176\u987a","title":"\u5fae\u4fe1\uff1azqs15755083308","page":{"permalink":"/blog/authors/zhouqishun"},"imageURL":"https://soft-where-21.github.io/file/graduation_work/avatar/%E5%91%A8%E5%85%B6%E9%A1%BA.jpg","key":"zhouqishun"}],"frontMatter":{"slug":"graduation-experience-zhou-qi-shun","title":"\u6bd5\u8bbe\u7ecf\u9a8c\u5206\u4eab\uff1a\u91cd\u89c6\u89c4\u8303\uff0c\u63d0\u524d\u51c6\u5907","authors":["zhouqishun"],"tags":["graduation-experience"],"description":"\u5468\u5176\u987a\u540c\u5b66\u5206\u4eab\u8f6f\u4ef6\u5b66\u9662\u672c\u79d1\u6bd5\u4e1a\u8bbe\u8ba1\u5f00\u9898\u3001\u4e2d\u671f\u4e0e\u7ed3\u9898\u9636\u6bb5\u7684\u51c6\u5907\u91cd\u70b9\u3002"},"unlisted":false,"prevItem":{"title":"\u6bd5\u8bbe\u7ecf\u9a8c\u5206\u4eab\uff1a\u6d41\u7a0b\u3001\u9009\u9898\u4e0e\u7b54\u8fa9","permalink":"/blog/graduation-experience-yan-jiahao"}},"content":"\u6bd5\u8bbe\u6574\u4f53\u5206\u4e3a\u5f00\u9898\u3001\u4e2d\u671f\u3001\u7ed3\u9898\u4e09\u4e2a\u9636\u6bb5\u3002\u8f6f\u4ef6\u5b66\u9662\u5f00\u9898\u8f83\u65e9\uff0c\u5728 11 \u6708\uff1b\u4e2d\u671f\u5728\u6b21\u5e74 4 \u6708\uff1b\u7ed3\u9898\u5728 6 \u6708\u3002\u8fd9\u4e5f\u610f\u5473\u7740\u5728\u4e2d\u671f\u65f6\uff0c\u57fa\u672c\u5df2\u7ecf\u8981\u5b8c\u6210\u4e3b\u8981\u5185\u5bb9\uff0c\u4e2d\u671f\u4ee5\u540e\u5219\u8fdb\u5165\u8bba\u6587\u64b0\u5199\u9636\u6bb5\u3002\\n\\n\u672c\u79d1\u6bd5\u4e1a\u8bbe\u8ba1\u5e76\u4e0d\u8981\u6c42\u5f88\u9ad8\u7684\u521b\u65b0\u6027\u3002\u867d\u7136\u6211\u5728\u8fc7\u7a0b\u4e2d\u7684\u5fc3\u6001\u662f\u201c\u8ba4\u4e3a\u4e0d\u4f1a\u5361\u6bd5\u4e1a\uff0c\u505a\u5b8c\u5c31\u884c\u201d\uff0c\u4f46\u4f9d\u65e7\u5728\u6700\u540e\u7684\u8bba\u6587\u683c\u5f0f\u8c03\u6574\u4e2d\u4f53\u4f1a\u5230\u4e86\u5b83\u7684\u4e25\u8083\u6027\u3002\u7855\u535a\u9636\u6bb5\u8fd8\u4f1a\u518d\u6b21\u7ecf\u5386\u5927\u8bba\u6587\u5199\u4f5c\uff0c\u56e0\u6b64\u5efa\u8bae\u5927\u5bb6\u65e0\u8bba\u5185\u5bb9\u5b8c\u6210\u5f97\u5982\u4f55\uff0c\u90fd\u8981\u91cd\u89c6\u8bba\u6587\u5199\u4f5c\uff0c\u591a\u79ef\u7d2f\u683c\u5f0f\u548c\u7248\u9762\u65b9\u9762\u7684\u6280\u5de7\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u6bd5\u8bbe\u5f00\u9898\\n\\n\u8fd9\u4e00\u9636\u6bb5\u9700\u8981\u786e\u5b9a\u6bd5\u4e1a\u8bbe\u8ba1\u7684\u5927\u65b9\u5411\u548c\u9884\u671f\u5185\u5bb9\u3002PPT \u4e3b\u8981\u9648\u8ff0\u9009\u9898\u80cc\u666f\u3001\u610f\u4e49\u3001\u76f8\u5173\u5de5\u4f5c\u8c03\u7814\u4ee5\u53ca\u521d\u6b65\u65b9\u6848\u3002\u5f00\u9898\u62a5\u544a\u5e94\u8be5\u6ca1\u6709\u4e8c\u8fa9\u7684\u786c\u6027\u6307\u6807\uff0c\u4f46\u6709\u7684\u7ec4\u4ecd\u53ef\u80fd\u5b89\u6392\u90e8\u5206\u540c\u5b66\u4e8c\u8fa9\u3002\\n\\n\u6bcf\u4e2a\u9636\u6bb5\u7684 PPT \u90fd\u5efa\u8bae\u8ba4\u771f\u6784\u601d\uff0c\u56e0\u4e3a\u5f00\u9898\u9636\u6bb5\u51c6\u5907\u597d\u7684\u80cc\u666f\u3001\u610f\u4e49\u548c\u76f8\u5173\u5de5\u4f5c\uff0c\u5728\u4e2d\u671f\u548c\u7ed3\u9898\u65f6\u57fa\u672c\u53ef\u4ee5\u76f4\u63a5\u590d\u7528\u3002\u56e0\u6b64\uff0c\u5f00\u9898\u65f6\u9009\u597d\u7b80\u6d01\u5927\u65b9\u7684\u6a21\u677f\u4e5f\u5f88\u91cd\u8981\u3002\\n\\n\u603b\u4e4b\uff0c\u5f00\u9898\u76f8\u5bf9\u8f7b\u677e\uff0c\u800c\u4e14\u8f6f\u4ef6\u5b66\u9662\u5f00\u9898\u65f6\u95f4\u5f88\u65e9\uff0c\u8fc7\u7a0b\u4e2d\u53d1\u73b0\u65b9\u5411\u4e0d\u5408\u9002\u65f6\uff0c\u901a\u5e38\u8fd8\u6709\u8c03\u6574\u6216\u6362\u9898\u7684\u7a7a\u95f4\u3002Just take it easy\u3002\\n\\n## \u6bd5\u8bbe\u4e2d\u671f\\n\\n\u6309\u5e38\u7406\u6765\u8bf4\uff0c\u8fd9\u4e00\u9636\u6bb5\u57fa\u672c\u9700\u8981\u5b8c\u6210\u6bd5\u8bbe\u7684\u6240\u6709\u5b9e\u9a8c\u5185\u5bb9\uff0c\u6240\u4ee5\u5927\u5bb6\u9700\u8981\u5728\u5bd2\u5047\u9636\u6bb5\u7a0d\u5fae\u52a0\u4e00\u628a\u52b2\u3002\u8001\u5e08\u4e0d\u4f1a\u8981\u6c42\u6574\u4e2a\u6846\u67b6\u6216\u7cfb\u7edf\u7684\u6700\u7ec8\u7ed3\u679c\uff0c\u4f46\u4f1a\u68c0\u67e5\u8bbe\u8ba1\u662f\u5426\u5408\u7406\u3001\u9a8c\u8bc1\u662f\u5426\u5145\u5206\uff0c\u4ee5\u786e\u8ba4\u5927\u5bb6\u80fd\u591f\u5728\u7ed3\u9898\u524d\u987a\u5229\u5b8c\u6210\u6240\u6709\u5185\u5bb9\u3002\\n\\n\u5468\u56f4\u5927\u591a\u6570\u540c\u5b66\u7684\u4e2d\u671f PPT \u548c\u7ed3\u9898 PPT \u76f8\u5dee\u4e0d\u5230 10%\uff0c\u6240\u4ee5\u4e2d\u671f\u57fa\u672c\u53ef\u4ee5\u6309\u7167\u7ed3\u9898\u8981\u6c42\u6765\u51c6\u5907\u3002\\n\\n\u5c3d\u91cf\u4e0d\u8981\u7b49\u5230\u4e2d\u671f\u7b54\u8fa9\u540e\u624d\u53d1\u73b0\u9898\u76ee\u4e0d\u5408\u7406\u6216\u8005\u65e0\u6cd5\u5b8c\u6210\uff0c\u5426\u5219\u518d\u6362\u9898\u4f1a\u6bd4\u8f83\u9ebb\u70e6\u3002\u4e2d\u671f\u6709\u4e8c\u8fa9\u7684\u786c\u6027\u6307\u6807\uff0c\u5e94\u5c3d\u91cf\u907f\u514d\u6210\u4e3a\u7ec4\u5185\u672b\u4f4d\u3002\\n\\n## \u6bd5\u8bbe\u7ed3\u9898\\n\\n\u6211\u5728\u8fd9\u4e2a\u8fc7\u7a0b\u4e2d\u6210\u529f\u6210\u4e3a\u4e86 Word \u9ad8\u624b\u3002\\n\\n\u5728\u7cfb\u7edf\u4e0a\u63d0\u4ea4\u8bba\u6587\u65f6\uff0c\u5fc5\u987b\u4f7f\u7528 Word \u8fdb\u884c\u683c\u5f0f\u5ba1\u67e5\u3002\u5373\u4f7f\u7cfb\u7edf\u4e2d\u7684\u5927\u91cf\u683c\u5f0f\u68c0\u67e5\u90fd\u901a\u8fc7\uff0c\u8bba\u6587\u5b9e\u9645\u4e0a\u4ecd\u53ef\u80fd\u5b58\u5728\u5f88\u591a\u95ee\u9898\u3002\u6211\u5728\u7b54\u8fa9\u73b0\u573a\u5c31\u56e0\u4e3a\u683c\u5f0f\u95ee\u9898\u88ab\u8001\u5e08\u4e25\u5389\u6307\u51fa\u3002\u5efa\u8bae\u63d0\u524d\u8bf7\u8981\u6c42\u4e25\u683c\u7684\u8001\u5e08\u6216\u5b66\u957f\u5e2e\u52a9\u68c0\u67e5\u3002\\n\\n\u7b54\u8fa9\u73b0\u573a\u7684\u8001\u5e08\u901a\u5e38\u4e0d\u4f1a\u518d\u4ed4\u7ec6\u770b PPT\uff0c\u4e5f\u4e0d\u4f1a\u8fc7\u5206\u6311\u5254\u8bba\u6587\u5185\u5bb9\uff0c\u4e3b\u8981\u68c0\u67e5\u8bba\u6587\u683c\u5f0f\uff0c\u5305\u62ec\u56fe\u7247\u5c3a\u5bf8\u548c\u5b57\u53f7\u3001\u5f15\u7528\u683c\u5f0f\u3001\u516c\u5f0f\u683c\u5f0f\u4ee5\u53ca\u6587\u5b57\u8868\u8fbe\u662f\u5426\u6e05\u6670\u3002\\n\\n\u7ec4\u5185\u672b\u4f4d\u4f1a\u8fdb\u5165\u590d\u5ba1\u73af\u8282\uff0c\u76f8\u5f53\u4e8e\u63d0\u524d\u62bd\u67e5\u3002\u5982\u679c\u8001\u5e08\u8ba4\u4e3a\u8bba\u6587\u5b58\u5728\u95ee\u9898\uff0c\u4f1a\u8981\u6c42\u56de\u6765\u7ee7\u7eed\u4fee\u6539\u3002\\n\\n## \u603b\u7ed3\\n\\n\u672c\u79d1\u6bd5\u8bbe\u662f\u4e00\u95e8\u66f4\u6ce8\u91cd\u89c4\u8303\u6027\u3001\u5bf9\u521b\u65b0\u6027\u8981\u6c42\u76f8\u5bf9\u6709\u9650\u7684\u8bfe\u7a0b\u3002\u5927\u5bb6\u53ef\u4ee5\u63d0\u524d\u9009\u62e9\u81ea\u5df1\u611f\u5174\u8da3\u7684\u65b9\u5411\uff0c\u5c3d\u91cf\u4e0e\u5347\u5b66\u540e\u7684\u7814\u7a76\u65b9\u5411\u4fdd\u6301\u4e00\u81f4\uff0c\u8ba9\u6240\u505a\u7684\u4e8b\u60c5\u5177\u6709\u5ef6\u7eed\u6027\u3002\\n\\n\u5f53\u5927\u5bb6\u770b\u5230\u8fd9\u7bc7\u968f\u7b14\u65f6\uff0c\u5df2\u7ecf\u6b65\u5165\u5927\u5b66\u7684\u6700\u540e\u4e00\u4e2a\u9636\u6bb5\u3002\u6bd5\u8bbe\u672c\u8eab\u7684\u8981\u6c42\u5e76\u4e0d\u9ad8\uff0c\u53ea\u9700\u8981\u8ba4\u771f\u5b8c\u6210\u5373\u53ef\uff0c\u4e5f\u522b\u5fd8\u4e86\u4eab\u53d7\u5927\u56db\u6700\u540e\u7684\u6821\u56ed\u751f\u6d3b\u3002\\n\\n\u795d\u524d\u8def\u5766\u8361\uff0c\u4e07\u4e8b\u53ef\u671f\u3002"}]}}')}}]);